import{n as e}from"./createLucideIcon-BgnLVNzM.js";import{t}from"./funnel-CgqU7Auq.js";import{t as n}from"./gift-C8Ifs_XL.js";import{H as r,R as i,U as a,c as o,ct as s,lt as c}from"./index-JSFVIT6u.js";import{i as l,n as u,r as d,t as f}from"./ContentBlocks-BWhIBUe6.js";var p=e(),m=[i,n,t,r],h={en:{seo:{title:`Find Creator Campaigns in Nepal | Paid Campaigns & Events`,description:`Browse paid campaigns and free open events on Kolab. Nepali content creators can find and apply to brand collaborations that fit their niche.`},breadcrumbName:`Find Campaigns`,eyebrow:`Find Campaigns`,heading:`Find Creator Campaigns in Nepal`,intro:`Paid brand deals and free open events don't have to land in your DMs by chance. Kolab lists live campaigns from Nepali brands — browse by category, platform, and city, and apply with a proposal to the ones that actually fit your content.`,faqs:[{question:`Where do I find campaigns to apply to on Kolab?`,answer:`Open the campaigns feed in the app, where every live paid campaign and open event from brands is listed with its budget (or exchange, for open events), category, platform, and deadline.`},{question:`What's the difference between a paid campaign and an open event?`,answer:`A paid campaign has a cash budget set by the brand for specific deliverables. An open event is free to attend or cover — you take part in exchange for content and exposure rather than a fee. Both are listed with their requirements up front.`},{question:`Can I filter campaigns to just my niche?`,answer:`Yes — filter the campaigns feed by category (fashion, food, tech, fitness, and more), by platform (Instagram, TikTok, YouTube, Facebook, and others), and by location anywhere in Nepal, so you only see campaigns relevant to you.`},{question:`How do I apply to a campaign?`,answer:`Open a campaign that fits your niche and submit a proposal. If the brand is interested, they'll respond and you can message directly in-app to align on deliverables and timeline.`},{question:`Do I see the budget before I apply?`,answer:`Yes — paid campaigns show their budget upfront, and open events describe what's offered in exchange, so you know what a collaboration is worth before you commit any time to a proposal.`},{question:`How and when do I get paid after applying to a paid campaign?`,answer:`Once your proposal is accepted and the work is delivered, payment is released from escrow after the brand approves it — the budget is held safely from the moment the campaign starts, so you're not waiting on trust alone.`}],related:[{label:`For Content Creators`,path:`/content-creators`,description:`Build your creator profile on Kolab.`},{label:`Creator Marketplace Nepal`,path:`/creator-marketplace-nepal`,description:`Kolab's full creator marketplace overview.`},{label:`TikTok Creators`,path:`/tiktok-creators`,description:`Platform-specific creator opportunities.`},{label:`For Brands`,path:`/brands`,description:`Post a campaign for creators to discover.`}],cta:{heading:`Ready to Find Your Next Campaign?`,sub:`Download Kolab and start applying today.`},sections:{stopWaiting:{heading:`Stop waiting for brands to find you`,paragraphs:[`Most creators in Nepal still find brand work the same passive way: a brand happens to notice their profile and sends a DM, or a friend forwards an opportunity secondhand. That works occasionally, but it puts a creator entirely at the mercy of who happens to be looking — with no way to actively go find paid work that fits their niche.`,`Kolab flips that around. Instead of waiting to be discovered, creators can browse a live feed of campaigns and open events posted directly by brands, see the budget and requirements upfront, and apply to the ones that actually make sense for their content — on their own schedule, not a brand's.`]},feed:{heading:`What you'll find in the campaigns feed`,benefits:[{title:`Paid campaigns`,desc:`Brands set a real budget for specific deliverables — visible before you apply, so you know exactly what a collaboration pays.`},{title:`Free open events`,desc:`Attend or cover an event in exchange for content and exposure — useful for building your portfolio and brand relationships.`},{title:`Filter to your niche`,desc:`Narrow the feed by category, platform, and city so you only see campaigns actually worth your time.`},{title:`Apply with a proposal`,desc:`Submit a proposal directly in-app, and message the brand once you're matched.`}]},howTo:{heading:`How to find and land your next campaign`,items:[`Open the campaigns feed and filter by category, platform, and location anywhere in Nepal.`,`Review the budget (or exchange, for open events), deliverables, and deadline for each listing.`,`Apply with a proposal to the campaigns that genuinely fit your content and audience.`,`Message the brand directly in-app once your proposal is accepted, and align on deliverables.`,`Deliver the work, and get paid from escrow once the brand approves it.`,`Leave and receive a review, building a track record that helps you land the next campaign faster.`]},trustBudget:{heading:`A budget you can trust before you apply`,paragraph:`One of the biggest frustrations with informal brand deals is finding out the "opportunity" was never really worth your time — a vague DM with no real budget attached. Every campaign on Kolab lists its budget or exchange terms before you apply, and paid campaigns are backed by escrow, so the budget is already secured by Kolab the moment you're matched. You're never guessing whether a brand can actually pay for the work they're asking for.`}}},ne:{seo:{title:`Find Creator Campaigns in Nepal | Paid Campaigns & Events`,description:`Browse paid campaigns and free open events on Kolab. Nepali content creators can find and apply to brand collaborations that fit their niche.`},breadcrumbName:`क्याम्पेन खोज्नुहोस्`,eyebrow:`क्याम्पेन खोज्नुहोस्`,heading:`नेपालमा क्रिएटर क्याम्पेनहरू फेला पार्नुहोस्`,intro:`तलबसहितका ब्रान्ड डिल र निःशुल्क खुला इभेन्टहरू संयोगले मात्र तपाईंको DM मा आउनुपर्दैन। Kolab ले नेपाली ब्रान्डका लाइभ क्याम्पेनहरू सूचीबद्ध गर्छ — श्रेणी, प्लेटफर्म, र सहरअनुसार ब्राउज गर्नुहोस्, र तपाईंको कन्टेन्टसँग वास्तवमै मिल्नेमा प्रस्तावसहित आवेदन दिनुहोस्।`,faqs:[{question:`Kolab मा आवेदन दिन क्याम्पेनहरू कहाँ फेला पार्ने?`,answer:`एपमा क्याम्पेन फिड खोल्नुहोस्, जहाँ ब्रान्डका सबै लाइभ तलबसहितका क्याम्पेन र खुला इभेन्टहरू आफ्नो बजेट (वा खुला इभेन्टका लागि साटासाट), श्रेणी, प्लेटफर्म, र समयसीमासहित सूचीबद्ध हुन्छन्।`},{question:`तलबसहितको क्याम्पेन र खुला इभेन्टबीच के फरक छ?`,answer:`तलबसहितको क्याम्पेनमा ब्रान्डले निश्चित डेलिभरेबलका लागि नगद बजेट तय गर्छ। खुला इभेन्टमा सहभागी हुन वा कभर गर्न निःशुल्क हुन्छ — तपाईं शुल्कको सट्टा सामग्री र एक्सपोजरको बदलामा भाग लिनुहुन्छ। दुवैका आवश्यकताहरू पहिले नै सूचीबद्ध गरिएका हुन्छन्।`},{question:`के म क्याम्पेनहरूलाई मेरो निचमा मात्र फिल्टर गर्न सक्छु?`,answer:`हो — क्याम्पेन फिडलाई श्रेणी (फेसन, खाना, प्रविधि, फिटनेस, र अरू धेरै), प्लेटफर्म (Instagram, TikTok, YouTube, Facebook, र अन्य), र नेपालभरि कुनै पनि स्थानअनुसार फिल्टर गर्नुहोस्, ताकि तपाईंलाई सान्दर्भिक क्याम्पेनहरू मात्र देखियोस्।`},{question:`क्याम्पेनमा कसरी आवेदन दिने?`,answer:`तपाईंको निचसँग मिल्ने क्याम्पेन खोल्नुहोस् र प्रस्ताव पेश गर्नुहोस्। ब्रान्ड इच्छुक भएमा, उनीहरूले जवाफ दिनेछन् र तपाईंले डेलिभरेबल र समयसीमामा सहमत हुन एपभित्रै सिधै म्यासेज गर्न सक्नुहुन्छ।`},{question:`के म आवेदन दिनुअघि नै बजेट देख्न सक्छु?`,answer:`हो — तलबसहितका क्याम्पेनहरूले आफ्नो बजेट पहिले नै देखाउँछन्, र खुला इभेन्टहरूले बदलामा के दिइन्छ भनेर वर्णन गर्छन्, त्यसैले प्रस्तावमा समय खर्च गर्नुअघि नै सहकार्यको मूल्य कति छ भन्ने तपाईंलाई थाहा हुन्छ।`},{question:`तलबसहितको क्याम्पेनमा आवेदन दिएपछि भुक्तानी कसरी र कहिले पाइन्छ?`,answer:`तपाईंको प्रस्ताव स्वीकृत भई काम बुझाइएपछि, ब्रान्डले स्वीकृत गरेपछि एस्क्रोबाट भुक्तानी रिलिज हुन्छ — क्याम्पेन सुरु भएको क्षणदेखि नै बजेट सुरक्षित राखिएको हुन्छ, त्यसैले तपाईंले भरोसामा मात्र पर्खनुपर्दैन।`}],related:[{label:`कन्टेन्ट क्रिएटरहरूका लागि`,path:`/content-creators`,description:`Kolab मा आफ्नो क्रिएटर प्रोफाइल बनाउनुहोस्।`},{label:`क्रिएटर मार्केटप्लेस नेपाल`,path:`/creator-marketplace-nepal`,description:`Kolab को सम्पूर्ण क्रिएटर मार्केटप्लेस झलक।`},{label:`TikTok क्रिएटरहरू`,path:`/tiktok-creators`,description:`प्लेटफर्म-विशेष क्रिएटर अवसरहरू।`},{label:`ब्रान्डहरूका लागि`,path:`/brands`,description:`क्रिएटरहरूले फेला पार्न क्याम्पेन पोस्ट गर्नुहोस्।`}],cta:{heading:`तपाईंको अर्को क्याम्पेन फेला पार्न तयार हुनुहुन्छ?`,sub:`Kolab डाउनलोड गर्नुहोस् र आजै आवेदन दिन सुरु गर्नुहोस्।`},sections:{stopWaiting:{heading:`ब्रान्डले तपाईंलाई फेला पारून् भनेर पर्खन छोड्नुहोस्`,paragraphs:[`नेपालमा धेरैजसो क्रिएटरहरूले अझै पनि उही निष्क्रिय तरिकाले ब्रान्ड काम फेला पार्छन्: ब्रान्डले संयोगले उनीहरूको प्रोफाइल देख्छ र DM पठाउँछ, वा साथीले कुनै अवसर सेकेन्डह्यान्ड पठाइदिन्छ। यो कहिलेकाहीं काम गर्छ, तर यसले क्रिएटरलाई पूर्ण रूपमा हेरिरहेको व्यक्तिको दयामा राख्छ — आफ्नो निचसँग मिल्ने तलबसहितको काम सक्रिय रूपमा खोज्ने कुनै तरिका बिना।`,`Kolab ले त्यसलाई उल्टाइदिन्छ। फेला पारिनको पर्खाइको सट्टा, क्रिएटरहरूले ब्रान्डहरूले सिधै पोस्ट गरेका क्याम्पेन र खुला इभेन्टहरूको लाइभ फिड ब्राउज गर्न सक्छन्, बजेट र आवश्यकता पहिले नै हेर्न सक्छन्, र आफ्नो कन्टेन्टसँग वास्तवमै मिल्नेमा — ब्रान्डको होइन, आफ्नै तालिकाअनुसार — आवेदन दिन सक्छन्।`]},feed:{heading:`क्याम्पेन फिडमा तपाईंले के पाउनुहुन्छ`,benefits:[{title:`तलबसहितका क्याम्पेनहरू`,desc:`ब्रान्डहरूले निश्चित डेलिभरेबलका लागि वास्तविक बजेट तय गर्छन् — तपाईंले आवेदन दिनुअघि नै देखिने, त्यसैले सहकार्यले कति तिर्छ भन्ने तपाईंलाई ठ्याक्कै थाहा हुन्छ।`},{title:`निःशुल्क खुला इभेन्टहरू`,desc:`सामग्री र एक्सपोजरको बदलामा इभेन्टमा उपस्थित हुनुहोस् वा कभर गर्नुहोस् — तपाईंको पोर्टफोलियो र ब्रान्ड सम्बन्ध निर्माणका लागि उपयोगी।`},{title:`तपाईंको निचमा फिल्टर गर्नुहोस्`,desc:`फिडलाई श्रेणी, प्लेटफर्म, र सहरअनुसार साँघुर्याउनुहोस् ताकि तपाईंले वास्तवमै तपाईंको समयको लायक क्याम्पेनहरू मात्र देख्नुहोस्।`},{title:`प्रस्तावसहित आवेदन दिनुहोस्`,desc:`एपभित्रै सिधै प्रस्ताव पेश गर्नुहोस्, र मिलान भएपछि ब्रान्डलाई म्यासेज गर्नुहोस्।`}]},howTo:{heading:`तपाईंको अर्को क्याम्पेन कसरी फेला पार्ने र प्राप्त गर्ने`,items:[`क्याम्पेन फिड खोल्नुहोस् र श्रेणी, प्लेटफर्म, र नेपालभरि कुनै पनि स्थानअनुसार फिल्टर गर्नुहोस्।`,`प्रत्येक लिस्टिङको बजेट (वा खुला इभेन्टका लागि साटासाट), डेलिभरेबल, र समयसीमा समीक्षा गर्नुहोस्।`,`तपाईंको कन्टेन्ट र दर्शकसँग साँच्चै मिल्ने क्याम्पेनहरूमा प्रस्तावसहित आवेदन दिनुहोस्।`,`तपाईंको प्रस्ताव स्वीकृत भएपछि एपभित्रै सिधै ब्रान्डलाई म्यासेज गर्नुहोस्, र डेलिभरेबलमा सहमत हुनुहोस्।`,`काम बुझाउनुहोस्, र ब्रान्डले स्वीकृत गरेपछि एस्क्रोबाट भुक्तानी पाउनुहोस्।`,`समीक्षा दिनुहोस् र लिनुहोस्, जसले तपाईंलाई अर्को क्याम्पेन छिटो प्राप्त गर्न मद्दत गर्ने ट्र्याक रेकर्ड बनाउँछ।`]},trustBudget:{heading:`आवेदन दिनुअघि नै भरोसा गर्न मिल्ने बजेट`,paragraph:`अनौपचारिक ब्रान्ड डिलको सबैभन्दा ठूलो झर्को भनेको "अवसर" वास्तवमा तपाईंको समयको लायक थिएन भनेर पछि थाहा पाउनु हो — कुनै वास्तविक बजेट नजोडिएको अस्पष्ट DM। Kolab मा प्रत्येक क्याम्पेनले आवेदन दिनुअघि नै आफ्नो बजेट वा साटासाटका सर्तहरू सूचीबद्ध गर्छ, र तलबसहितका क्याम्पेनहरू एस्क्रोद्वारा सुरक्षित हुन्छन्, त्यसैले तपाईं मिलान हुनेबित्तिकै बजेट Kolab ले पहिले नै सुरक्षित गरिसकेको हुन्छ। ब्रान्डले माग गरेको काम तिर्न सक्छ कि सक्दैन भनेर तपाईंले कहिल्यै अनुमान लगाउनुपर्दैन।`}}}};function g(){return(0,p.jsx)(s,{children:(0,p.jsx)(_,{})})}function _(){let{lang:e,d:t}=c(),n=h[e];return(0,p.jsxs)(l,{seo:{title:n.seo.title,description:n.seo.description,path:`/find-campaigns`,keywords:[`creator opportunities Nepal`,`paid campaigns Nepal`,`creator jobs Nepal`,`brand campaign Nepal`,`content creator jobs Nepal`,`influencer jobs Nepal`,`work with brands Nepal`,`influencer opportunities Nepal`],jsonLd:o({path:`/find-campaigns`,title:`Find Creator Campaigns in Nepal | Kolab`,description:`Browse paid campaigns and free open events for content creators in Nepal.`})},breadcrumb:[{name:t.contentPage.home,path:`/`},{name:n.breadcrumbName,path:`/find-campaigns`}],icon:a,eyebrow:n.eyebrow,heading:n.heading,intro:n.intro,faqs:n.faqs,related:n.related,cta:n.cta,children:[(0,p.jsx)(d,{heading:n.sections.stopWaiting.heading,children:n.sections.stopWaiting.paragraphs.map((e,t)=>(0,p.jsx)(`p`,{children:e},t))}),(0,p.jsx)(d,{heading:n.sections.feed.heading,children:(0,p.jsx)(f,{items:n.sections.feed.benefits.map((e,t)=>({icon:m[t],title:e.title,desc:e.desc}))})}),(0,p.jsx)(d,{heading:n.sections.howTo.heading,children:(0,p.jsx)(u,{items:n.sections.howTo.items})}),(0,p.jsx)(d,{heading:n.sections.trustBudget.heading,children:(0,p.jsx)(`p`,{children:n.sections.trustBudget.paragraph})})]})}export{g as FindCampaignsPage};